'use client';

import { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { shopService } from '@/modules/shop/services/shopService';
import { ShopItem } from '@/modules/shop/types';
import { formatCurrency } from '@/utils';
import { Loader2, CheckCircle2, ShieldCheck, Truck, Zap, Plus, ShoppingBag } from 'lucide-react';
import Link from 'next/link';
import { useCart } from '@/modules/shop/context/CartContext';

export default function ItemDetailPage() {
    const params = useParams();
    const router = useRouter();
    const itemId = params.itemId as string;
    const { addToCart } = useCart();

    const [item, setItem] = useState<ShopItem | null>(null);
    const [loading, setLoading] = useState(true);
    const [selections, setSelections] = useState<Record<string, string>>({});
    const [quantity, setQuantity] = useState(1);

    useEffect(() => {
        const load = async () => {
            setLoading(true);
            const data = await shopService.getItemById(itemId);
            if (data) {
                setItem(data);
                // Initialize selections with first choice or empty
                const initial: Record<string, string> = {};
                data.options?.forEach(opt => {
                    if (opt.type === 'select' && opt.choices) {
                        initial[opt.id] = opt.choices[0];
                    }
                });
                setSelections(initial);
            }
            setLoading(false);
        };
        load();
    }, [itemId]);

    const handleAddToCart = () => {
        if (!item) return;
        addToCart(item, selections, quantity);
        alert(`${item.name} added to cart!`);
    };

    const handleBuyNow = () => {
        if (!item) return;
        addToCart(item, selections, quantity);
        router.push('/shop/checkout');
    };

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[500px] gap-4">
                <Loader2 className="animate-spin text-emerald-600 w-10 h-10" />
            </div>
        );
    }

    if (!item) {
        return (
            <div className="text-center py-20">
                <h1 className="text-4xl font-black text-slate-900 mb-4">Item Not Found</h1>
                <Link href="/shop" className="text-emerald-600 font-bold hover:underline">Return to Shop</Link>
            </div>
        );
    }

    return (
        <div className="animate-in fade-in duration-700 space-y-12 pb-20">
            {/* Breadcrumb */}
            <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 capitalize">
                <Link href="/shop" className="hover:text-slate-600">Home</Link>
                <span>/</span>
                <Link href={`/shop/${item.category}`} className="hover:text-slate-600">{item.category}</Link>
                <span>/</span>
                <span className="text-slate-900">{item.name}</span>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-start">
                {/* Left: Product Images */}
                <div className="space-y-6">
                    <div className="aspect-square rounded-[3rem] overflow-hidden bg-slate-100 border border-slate-100 shadow-xl shadow-slate-200/50">
                        <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
                    </div>
                    <div className="grid grid-cols-3 gap-6">
                        {[1, 2, 3].map((i) => (
                            <div key={i} className="aspect-square rounded-3xl overflow-hidden bg-slate-100 border border-slate-200 opacity-60 hover:opacity-100 transition-opacity cursor-pointer">
                                <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
                            </div>
                        ))}
                    </div>
                </div>

                {/* Right: Product Details */}
                <div className="space-y-10">
                    <div className="space-y-4">
                        <div className="flex items-center gap-3">
                            <span className="px-3 py-1 bg-emerald-50 text-emerald-600 rounded-lg text-[10px] font-black uppercase tracking-[0.2em]">
                                {item.stockStatus}
                            </span>
                        </div>
                        <h1 className="text-5xl font-black text-slate-900 tracking-tighter leading-tight">
                            {item.name}
                        </h1>
                        <p className="text-lg text-slate-500 font-medium leading-relaxed">
                            {item.description}
                        </p>
                    </div>

                    <div className="p-8 bg-white rounded-[2.5rem] border border-slate-200/60 shadow-sm space-y-8">
                        <div>
                            <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2">Unit Price</p>
                            <div className="flex items-baseline gap-2">
                                <span className="text-5xl font-black text-slate-900 tracking-tighter">
                                    {formatCurrency(item.price)}
                                </span>
                                <span className="text-sm font-bold text-slate-400">
                                    {item.billingType === 'MONTHLY' ? '/ per month' : 'each'}
                                </span>
                            </div>
                        </div>

                        {/* Customization Options */}
                        {item.options && item.options.length > 0 && (
                            <div className="space-y-6 pt-6 border-t border-slate-100">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    {item.options.map((opt) => (
                                        <div key={opt.id} className="space-y-3">
                                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{opt.label} :</label>
                                            {opt.type === 'select' ? (
                                                <select
                                                    value={selections[opt.id]}
                                                    onChange={(e) => setSelections(prev => ({ ...prev, [opt.id]: e.target.value }))}
                                                    className="w-full h-12 px-4 bg-slate-50 border border-slate-100 rounded-xl font-bold text-sm outline-none focus:ring-2 focus:ring-emerald-600/20"
                                                >
                                                    {opt.choices?.map(choice => (
                                                        <option key={choice} value={choice}>{choice}</option>
                                                    ))}
                                                </select>
                                            ) : opt.type === 'text' ? (
                                                <input
                                                    type="text"
                                                    placeholder={opt.placeholder}
                                                    value={selections[opt.id] || ''}
                                                    onChange={(e) => setSelections(prev => ({ ...prev, [opt.id]: e.target.value }))}
                                                    className="w-full h-12 px-4 bg-slate-50 border border-slate-100 rounded-xl font-bold text-sm outline-none focus:ring-2 focus:ring-emerald-600/20"
                                                />
                                            ) : (
                                                <div className="border-2 border-dashed border-slate-200 rounded-xl p-4 flex flex-col items-center justify-center gap-2 bg-slate-50/50 hover:bg-white transition-all cursor-pointer">
                                                    <Zap size={16} className="text-emerald-600" />
                                                    <p className="text-[9px] font-black text-slate-500 uppercase">Upload File</p>
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                    <div className="space-y-3">
                                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Quantity :</label>
                                        <div className="flex items-center gap-4">
                                            <button
                                                onClick={() => setQuantity(Math.max(1, quantity - 1))}
                                                className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-600 hover:bg-slate-200"
                                            >-</button>
                                            <span className="font-black text-slate-900">{quantity}</span>
                                            <button
                                                onClick={() => setQuantity(quantity + 1)}
                                                className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-600 hover:bg-slate-200"
                                            >+</button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        <div className="pt-6 border-t border-slate-100 flex flex-col gap-4">
                            <div className="grid grid-cols-2 gap-4">
                                <button
                                    onClick={handleAddToCart}
                                    className="h-16 bg-slate-100 text-slate-600 rounded-3xl flex items-center justify-center gap-2 text-sm font-black uppercase tracking-widest hover:bg-slate-200 active:scale-95 transition-all"
                                >
                                    <ShoppingBag size={18} />
                                    Add To Cart
                                </button>
                                <button
                                    onClick={handleBuyNow}
                                    className="h-16 bg-emerald-600 shadow-2xl shadow-emerald-100 text-white rounded-3xl flex items-center justify-center text-sm font-black uppercase tracking-widest hover:bg-emerald-700 active:scale-95 transition-all"
                                >
                                    Secure Buy Now
                                </button>
                            </div>

                            <div className="flex items-center justify-center gap-8 py-2">
                                <div className="flex flex-col items-center gap-1 opacity-40">
                                    <Truck size={20} className="text-slate-900" />
                                    <span className="text-[9px] font-black uppercase">Fast Delivery</span>
                                </div>
                                <div className="flex flex-col items-center gap-1 opacity-40">
                                    <ShieldCheck size={20} className="text-slate-900" />
                                    <span className="text-[9px] font-black uppercase">Secure Payment</span>
                                </div>
                                <div className="flex flex-col items-center gap-1 opacity-40">
                                    <Zap size={20} className="text-slate-900" />
                                    <span className="text-[9px] font-black uppercase">Instant Setup</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
